// HeadBucket implements mm_client.MetadataClient
func (mmHeadBucket *MetadataClientMock) HeadBucket(ctx context.Context, bucket string) (b1 bool, err error) {
	mm_atomic.AddUint64(&mmHeadBucket.beforeHeadBucketCounter, 1)
	defer mm_atomic.AddUint64(&mmHeadBucket.afterHeadBucketCounter, 1)

	mmHeadBucket.t.Helper()

	if mmHeadBucket.inspectFuncHeadBucket != nil {
		mmHeadBucket.inspectFuncHeadBucket(ctx, bucket)
	}

	mm_params := MetadataClientMockHeadBucketParams{ctx, bucket}

	// Record call args
	mmHeadBucket.HeadBucketMock.mutex.Lock()
	mmHeadBucket.HeadBucketMock.callArgs = append(mmHeadBucket.HeadBucketMock.callArgs, &mm_params)
	mmHeadBucket.HeadBucketMock.mutex.Unlock()

	for _, e := range mmHeadBucket.HeadBucketMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.b1, e.results.err
		}
	}

	if mmHeadBucket.HeadBucketMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmHeadBucket.HeadBucketMock.defaultExpectation.Counter, 1)
		mm_want := mmHeadBucket.HeadBucketMock.defaultExpectation.params
		mm_want_ptrs := mmHeadBucket.HeadBucketMock.defaultExpectation.paramPtrs

		mm_got := MetadataClientMockHeadBucketParams{ctx, bucket}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmHeadBucket.t.Errorf("MetadataClientMock.HeadBucket got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmHeadBucket.HeadBucketMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.bucket != nil && !minimock.Equal(*mm_want_ptrs.bucket, mm_got.bucket) {
				mmHeadBucket.t.Errorf("MetadataClientMock.HeadBucket got unexpected parameter bucket, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmHeadBucket.HeadBucketMock.defaultExpectation.expectationOrigins.originBucket, *mm_want_ptrs.bucket, mm_got.bucket, minimock.Diff(*mm_want_ptrs.bucket, mm_got.bucket))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmHeadBucket.t.Errorf("MetadataClientMock.HeadBucket got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmHeadBucket.HeadBucketMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmHeadBucket.HeadBucketMock.defaultExpectation.results
		if mm_results == nil {
			mmHeadBucket.t.Fatal("No results are set for the MetadataClientMock.HeadBucket")
		}
		return (*mm_results).b1, (*mm_results).err
	}
	if mmHeadBucket.funcHeadBucket != nil {
		return mmHeadBucket.funcHeadBucket(ctx, bucket)
	}
	mmHeadBucket.t.Fatalf("Unexpected call to MetadataClientMock.HeadBucket. %v %v", ctx, bucket)
	return
}

